import base64
import os
from typing import Union

import boto3
from botocore.config import Config


def decrypt_ciphertext(ciphertext: Union[str, bytes], region_name: str = None) -> bytes:
    kms = boto3.client(
        "kms",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"),
        config=Config(retries={"max_attempts": 3, "mode": "standard"}),
    )

    if isinstance(ciphertext, str):
        try:
            ciphertext_blob = base64.b64decode(ciphertext, validate=True)
        except Exception:
            ciphertext_blob = ciphertext.encode("utf-8")
    else:
        ciphertext_blob = ciphertext

    response = kms.decrypt(CiphertextBlob=ciphertext_blob)
    return response["Plaintext"]
